import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 33.33, C: 100, D: 0.1 }
const pricing = { priceOf: async (sku) => prices[sku] }

async function withApp(fn) {
  const server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  const base = `http://localhost:${server.address().port}`
  try { return await fn(base) } finally { await new Promise((r) => server.close(r)) }
}

const post = async (base, items) => {
  const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items }) })
  return { status: res.status, body: await res.json() }
}

// Each case pins the CURRENT behaviour: 10% off when raw total > 100, then floored to whole euros.
const cases = [
  ['no discount, small order', [{ sku: 'A', qty: 3 }], 30],
  ['exactly 100 gets no discount', [{ sku: 'A', qty: 10 }], 100],
  ['just over 100 is discounted (100.1 -> 90.09 -> 90)', [{ sku: 'C', qty: 1 }, { sku: 'D', qty: 1 }], 90],
  ['101 -> 90.9 floored to 90', [{ sku: 'A', qty: 10 }, { sku: 'D', qty: 10 }], 90],
  ['large order 1000 -> 900', [{ sku: 'C', qty: 10 }], 900],
  ['mixed items, fractional: 33.33*5=166.65 -> 149.985 -> 149', [{ sku: 'B', qty: 5 }], 149],
  ['floor on undiscounted fractional: 33.33*3=99.99 -> 99', [{ sku: 'B', qty: 3 }], 99],
  ['multiple lines combined: 100+50 = 150 -> 135', [{ sku: 'C', qty: 1 }, { sku: 'A', qty: 5 }], 135],
]

for (const [name, items, total] of cases) {
  test(`total: ${name}`, () => withApp(async (base) => {
    const { status, body } = await post(base, items)
    assert.equal(status, 201)
    assert.equal(body.total, total)
  }))
}

test('stored order returns the same total', () => withApp(async (base) => {
  const { body } = await post(base, [{ sku: 'C', qty: 10 }])
  const fetched = await (await fetch(`${base}/orders/${body.id}`)).json()
  assert.equal(fetched.total, 900)
}))

test('empty items rejected', () => withApp(async (base) => {
  assert.equal((await post(base, [])).status, 400)
}))
EOF
